mapper.select:
SELECT DISTINCT p.id AS plan_id, s.scene_id AS skill_id
FROM swe_wealth_plans p JOIN swe_wealth_plan_scenes s ON s.plan_id = p.id

  AND p.bbk_id = #{bbkId}
  AND p.bbk_org_id = #{orgId}

SELECT DISTINCT plan_id, sence_id AS skill_id FROM swe_plan_sence_cron
WHERE execute_day >= #{query.startDate} AND execute_day <= #{query.endDate}

  AND sence_id IN
  #{skill}

SELECT DISTINCT u.first_bbk_id AS bbk_id, u.first_bbk_nm AS bbk_name,
  u.org_id, u.org_nm AS org_name, u.pst_lvl AS level, u.user_name, t.sap_id, p.id AS plan_id, p.created_at
FROM rm_jkh_user_info u
JOIN swe_wealth_plan_targets t ON t.sap_id COLLATE utf8mb4_bin = u.user_id AND t.deleted = 0
JOIN swe_wealth_plans p ON p.id = t.plan_id AND p.deleted = 0

  AND p.id IN
  #{id}
  AND u.first_bbk_id = #{query.bbkId}
  AND u.org_id = #{query.orgId}
  AND u.pst_lvl = #{query.level}

SELECT first_bbk_id AS bbk_id, first_bbk_nm AS bbk_name, org_id, org_nm AS org_name
FROM rm_jkh_user_info WHERE first_bbk_id = #{bbkId} AND org_id = #{orgId}
ORDER BY user_id LIMIT 1

mapper.sql:
WITH scheduled AS ( SELECT DISTINCT CAST(u.first_bbk_id AS BINARY) AS bbk_id, CAST(u.org_id AS BINARY) AS org_id, CAST(t.sap_id AS BINARY) AS sap_id, CAST(p.id AS BINARY) AS plan_id, u.first_bbk_nm AS bbk_name, u.org_nm AS org_name, u.user_name, u.pst_lvl AS level, p.source_label, p.created_at, CAST(s.scene_id AS BINARY) AS skill_id, k.skill_name, CAST(j.id AS BINARY) AS job_id, CAST(c.execute_day AS DATE) AS execution_day FROM swe_wealth_plans p INNER JOIN swe_wealth_plan_targets t ON t.plan_id = p.id AND t.deleted = 0 INNER JOIN rm_jkh_user_info u ON t.sap_id COLLATE utf8mb4_bin = u.user_id INNER JOIN swe_wealth_plan_scenes s ON s.plan_id = p.id AND s.deleted = 0 INNER JOIN swe_marketplace_skills k ON k.skill_id = s.scene_id AND k.source_id = 'RMASSIST' INNER JOIN swe_cron_jobs j ON j.plan_id = p.id AND j.tenant_id = t.sap_id AND j.skill_ids = s.scene_id AND j.source_id = 'RMASSIST' AND j.status != 'deleted' INNER JOIN swe_plan_sence_cron c ON c.plan_id = CAST(p.id AS BINARY) AND c.sence_id = CAST(s.scene_id AS BINARY) AND c.execute_day >= #{query.startDate} AND c.execute_day <= #{query.endDate} WHERE p.deleted = 0 AND p.source_label IN ('我的关注', '分行中台', '行长关注') AND u.first_bbk_id = #{query.bbkId} AND u.org_id = #{query.orgId} AND u.pst_lvl = #{query.level}
AND s.scene_id IN #{skill}
), candidates AS ( SELECT DISTINCT s.job_id, s.execution_day, e.id, CAST(e.trace_id AS BINARY) AS trace_id, e.actual_time, e.status FROM scheduled s INNER JOIN swe_cron_executions e ON e.job_id = s.job_id AND e.actual_time >= s.execution_day AND e.actual_time < DATE_ADD(s.execution_day, INTERVAL 1 DAY) AND e.actual_time >= s.created_at ), ranked AS ( SELECT job_id, execution_day, trace_id, actual_time, status, ROW_NUMBER() OVER (PARTITION BY job_id, execution_day ORDER BY actual_time DESC, id DESC) AS row_num FROM candidates ), selected AS ( SELECT job_id, execution_day, trace_id, actual_time, status FROM ranked WHERE row_num = 1 ), executed AS ( SELECT DISTINCT s.bbk_id, s.org_id, s.sap_id, s.plan_id, s.skill_id, s.skill_name, s.job_id, s.execution_day, s.bbk_name, s.org_name, s.user_name, s.level, s.source_label, CAST(x.trace_id AS BINARY) AS trace_id, x.is_read FROM scheduled s INNER JOIN selected e ON e.job_id = s.job_id AND e.execution_day = s.execution_day INNER JOIN swe_cron_executions x ON x.job_id = s.job_id AND ((e.trace_id IS NOT NULL AND x.trace_id = e.trace_id) OR (e.trace_id IS NULL AND x.actual_time = e.actual_time)) AND x.actual_time >= s.execution_day AND x.actual_time < DATE_ADD(s.execution_day, INTERVAL 1 DAY) AND x.actual_time >= s.created_at )
